	// ------------------------------
	// GENERIC ROW MAPPER
	// ------------------------------
	public static class GenericRowMapper<T> implements RowMapper<T> {
		private final Class<T> mappedClass;

		public GenericRowMapper(Class<T> mappedClass) {
			this.mappedClass = mappedClass;
		}

		@Override
		public T mapRow(ResultSet rs, int rowNum) throws SQLException {
			try {
				T obj = mappedClass.getDeclaredConstructor().newInstance();
				java.sql.ResultSetMetaData metaData = rs.getMetaData();
				int columnCount = metaData.getColumnCount();
				for (int i = 1; i <= columnCount; i++) {
					String columnName = metaData.getColumnName(i);
					Object value = rs.getObject(columnName);
					if (value == null) {
						continue;
					}
					String setterName = "set" + columnName.toUpperCase();
					String cleanSetterName = setterName.replace("_", "");
					for (java.lang.reflect.Method method : mappedClass.getMethods()) {
						String cleanMethodName = method.getName().replace("_", "");
						if (cleanMethodName.equalsIgnoreCase(cleanSetterName) && method.getParameterCount() == 1) {
							Class<?> paramType = method.getParameterTypes()[0];
							Object convertedValue = convertValue(value, paramType);
							method.invoke(obj, convertedValue);
							break;
						}
					}
				}
				return obj;
			} catch (Exception e) {
				throw new SQLException("Error mapping row for " + mappedClass.getSimpleName(), e);
			}
		}

		private Object convertValue(Object value, Class<?> targetType) {
			if (value == null) {
				return null;
			}
			if (targetType.isAssignableFrom(value.getClass())) {
				return value;
			}
			if (targetType == String.class) {
				return value.toString();
			}
			if (targetType == java.math.BigDecimal.class) {
				return new java.math.BigDecimal(value.toString());
			}
			if (targetType == Date.class) {
				if (value instanceof java.sql.Date) {
					return new Date(((java.sql.Date) value).getTime());
				}
				if (value instanceof java.sql.Timestamp) {
					return new Date(((java.sql.Timestamp) value).getTime());
				}
			}
			return value;
		}
	}

	// ------------------------------
	// FETCH DATA BY DATE
	// ------------------------------
	private <T> List<T> getdatabydateList(Date reportDate, String tableName, Class<T> clazz) {
		String sql = "SELECT * FROM " + tableName + " WHERE REPORT_DATE = ?";
		return jdbcTemplate.query(sql, new Object[]{reportDate}, new GenericRowMapper<>(clazz));
	}

	// ------------------------------
	// FETCH DATA BY DATE AND VERSION
	// ------------------------------
	private <T> List<T> getdatabydateListarchival(Date reportDate, java.math.BigDecimal reportVersion, String tableName, Class<T> clazz) {
		String sql = "SELECT * FROM " + tableName + " WHERE REPORT_DATE = ? AND REPORT_VERSION = ?";
		return jdbcTemplate.query(sql, new Object[]{reportDate, reportVersion}, new GenericRowMapper<>(clazz));
	}

	// ------------------------------
	// FETCH LATEST ARCHIVAL VERSION BY DATE
	// ------------------------------
	private <T> java.util.Optional<T> getLatestArchivalVersionByDate(Date reportDate, String tableName, Class<T> clazz) {
		String sql = "SELECT * FROM " + tableName + " WHERE REPORT_DATE = ? AND REPORT_VERSION IS NOT NULL ORDER BY TO_NUMBER(REPORT_VERSION) DESC FETCH FIRST 1 ROWS ONLY";
		List<T> list = jdbcTemplate.query(sql, new Object[]{reportDate}, new GenericRowMapper<>(clazz));
		return list.isEmpty() ? java.util.Optional.empty() : java.util.Optional.of(list.get(0));
	}

	// ------------------------------
	// FIND ENTITY BY ID
	// ------------------------------
	private <T> java.util.Optional<T> findEntityById(Date reportDate, String tableName, Class<T> clazz) {
		String sql = "SELECT * FROM " + tableName + " WHERE REPORT_DATE = ?";
		List<T> list = jdbcTemplate.query(sql, new Object[]{reportDate}, new GenericRowMapper<>(clazz));
		return list.isEmpty() ? java.util.Optional.empty() : java.util.Optional.of(list.get(0));
	}

	// ------------------------------
	// FIND ENTITY BY ID AND VERSION
	// ------------------------------
	private <T> java.util.Optional<T> findEntityByIdAndVersion(Date reportDate, java.math.BigDecimal reportVersion, String tableName, Class<T> clazz) {
		String sql = "SELECT * FROM " + tableName + " WHERE REPORT_DATE = ? AND REPORT_VERSION = ?";
		List<T> list = jdbcTemplate.query(sql, new Object[]{reportDate, reportVersion}, new GenericRowMapper<>(clazz));
		return list.isEmpty() ? java.util.Optional.empty() : java.util.Optional.of(list.get(0));
	}

	// ------------------------------
	// FETCH DATA WITH VERSION ALL
	// ------------------------------
	private <T> List<T> getdatabydateListWithVersion(String tableName, Class<T> clazz) {
		String sql = "SELECT * FROM " + tableName + " WHERE REPORT_VERSION IS NOT NULL ORDER BY REPORT_VERSION ASC";
		return jdbcTemplate.query(sql, new GenericRowMapper<>(clazz));
	}

	// ------------------------------
	// FETCH ARCHIVAL VERSION FOR COMBO BOX
	// ------------------------------
	private List<Object> getM_RPDarchival(String tableName) {
		String sql = "select REPORT_DATE, REPORT_VERSION from " + tableName + " order by REPORT_VERSION";
		return jdbcTemplate.query(sql, (rs, rowNum) -> new Object[]{rs.getDate("REPORT_DATE"), rs.getBigDecimal("REPORT_VERSION")});
	}

	// ------------------------------
	// DYNAMIC SAVE OR UPDATE ENTITY
	// ------------------------------
	private void saveEntity(Object entity, String tableName, boolean isArchivalOrResub) {
		try {
			Date reportDate = (Date) entity.getClass().getMethod("getReportDate").invoke(entity);
			java.math.BigDecimal reportVersion = null;
			if (isArchivalOrResub) {
				reportVersion = (java.math.BigDecimal) entity.getClass().getMethod("getReportVersion").invoke(entity);
			}

			String checkSql;
			Object[] checkArgs;
			if (isArchivalOrResub) {
				checkSql = "SELECT COUNT(*) FROM " + tableName + " WHERE REPORT_DATE = ? AND REPORT_VERSION = ?";
				checkArgs = new Object[]{reportDate, reportVersion};
			} else {
				checkSql = "SELECT COUNT(*) FROM " + tableName + " WHERE REPORT_DATE = ?";
				checkArgs = new Object[]{reportDate};
			}

			Integer count = jdbcTemplate.queryForObject(checkSql, checkArgs, Integer.class);
			boolean exists = (count != null && count > 0);

			java.util.List<String> colNames = new java.util.ArrayList<>();
			java.util.List<Object> values = new java.util.ArrayList<>();

			for (java.lang.reflect.Method method : entity.getClass().getMethods()) {
				if (method.getName().startsWith("get") && method.getParameterCount() == 0) {
					String propName = method.getName().substring(3);
					if ("Class".equals(propName)) {
						continue;
					}

					String setterName = "set" + propName;
					boolean hasSetter = false;
					for (java.lang.reflect.Method m : entity.getClass().getMethods()) {
						if (m.getName().equals(setterName) && m.getParameterCount() == 1) {
							hasSetter = true;
							break;
						}
					}
					if (!hasSetter) {
						continue;
					}

					String columnName = propName.toUpperCase();
					if ("REPORTDATE".equalsIgnoreCase(propName)) {
						columnName = "REPORT_DATE";
					} else if ("REPORTVERSION".equalsIgnoreCase(propName)) {
						columnName = "REPORT_VERSION";
					} else if ("REPORTRESUBDATE".equalsIgnoreCase(propName)) {
						columnName = "REPORT_RESUB_DATE";
					}

					Object val = method.invoke(entity);
					colNames.add(columnName);
					values.add(val);
				}
			}

			if (exists) {
				StringBuilder sb = new StringBuilder("UPDATE ");
				sb.append(tableName).append(" SET ");
				java.util.List<Object> updateArgs = new java.util.ArrayList<>();
				boolean first = true;
				for (int i = 0; i < colNames.size(); i++) {
					String col = colNames.get(i);
					if ("REPORT_DATE".equals(col) || "REPORT_VERSION".equals(col)) {
						continue;
					}
					if (!first) {
						sb.append(", ");
					}
					sb.append(col).append(" = ?");
					updateArgs.add(values.get(i));
					first = false;
				}
				if (isArchivalOrResub) {
					sb.append(" WHERE REPORT_DATE = ? AND REPORT_VERSION = ?");
					updateArgs.add(reportDate);
					updateArgs.add(reportVersion);
				} else {
					sb.append(" WHERE REPORT_DATE = ?");
					updateArgs.add(reportDate);
				}
				jdbcTemplate.update(sb.toString(), updateArgs.toArray());
			} else {
				StringBuilder sb = new StringBuilder("INSERT INTO ");
				sb.append(tableName).append(" (");
				StringBuilder placeholders = new StringBuilder();
				for (int i = 0; i < colNames.size(); i++) {
					if (i > 0) {
						sb.append(", ");
						placeholders.append(", ");
					}
					sb.append(colNames.get(i));
					placeholders.append("?");
				}
				sb.append(") VALUES (").append(placeholders).append(")");
				jdbcTemplate.update(sb.toString(), values.toArray());
			}
		} catch (Exception e) {
			throw new RuntimeException("Error saving entity to table " + tableName, e);
		}
	}

// ------------------------------
// M_RPD_PK CLASS DEFINITION
// ------------------------------
public static class M_RPD_PK implements Serializable {

    private Date reportDate;
    private BigDecimal reportVersion;

    // default constructor
    public M_RPD_PK() {}

    // parameterized constructor
    public M_RPD_PK(Date reportDate, BigDecimal reportVersion) {
        this.reportDate = reportDate;
        this.reportVersion = reportVersion;
    }

    // equals and hashCode
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof M_RPD_PK)) return false;
        M_RPD_PK that = (M_RPD_PK) o;
        return Objects.equals(reportDate, that.reportDate) &&
               Objects.equals(reportVersion, that.reportVersion);
    }

    @Override
    public int hashCode() {
        return Objects.hash(reportDate, reportVersion);
    }

    // getters & setters
    public Date getReportDate() { return reportDate; }
    public void setReportDate(Date reportDate) { this.reportDate = reportDate; }

    public BigDecimal getReportVersion() { return reportVersion; }
    public void setReportVersion(BigDecimal reportVersion) { this.reportVersion = reportVersion; }
}




